referenceSolutionTemplate:
with open("通讯录.txt", "w", encoding="utf-8") as 档案:
    档案.write("{k1}|{p1}\n{k2}|{p2}\n")

通讯录 = {}
with open("通讯录.txt", encoding="utf-8") as 档案:
    for 行 in 档案:
        行 = 行.strip()
        if not 行:
            continue
        名字, 号码 = 行.split("|", 1)
        通讯录[名字] = 号码

for _ in range(3):
    要查 = input()
    print(要查, "的号码是", 通讯录.get(要查, "查不到喵"))
